<script setup lang="ts">
/**
 * A paragraph of body text (`design/components/text.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/text.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed } from 'vue'

import styles from '@polymorph/recipes/structure/text.module.css'

export type TextSize = NonNullable<TextProps['size']>

export type TextTone = NonNullable<TextProps['tone']>

export interface TextProps {
  /**
   * The most lines the paragraph draws; the last ends with an ellipsis. Only the drawing is cut,
   * so the whole text must be reachable another way (the page it opens, a detail view). A value
   * that is not a whole number reads as the whole number below it, and below 1 nothing is cut.
   */
  lines?: number
  size?: 'sm' | 'md'
  /**
   * Never below secondary; muted text is a caption, and captions belong to the components that
   * own them.
   */
  tone?: 'primary' | 'secondary'
}

defineOptions({ name: 'Text', inheritAttrs: false })

const props = withDefaults(defineProps<TextProps>(), { size: 'md', tone: 'primary' })
defineSlots<{ default: (props: Record<string, never>) => unknown }>()
const kept = computed(() => (props.lines === undefined ? 0 : Math.floor(props.lines)))
const clamped = computed(() => kept.value >= 1)
</script>

<template>
  <p
    :class="styles.text"
    :style="{ '--pm-text-clamp': clamped ? kept : undefined }"
    :data-size="size"
    :data-tone="tone"
    :data-lines="clamped ? kept : undefined"
    data-member="text"
  >
    <slot />
  </p>
</template>
